using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.util;
using ghidra.program.util;

public class DefaultEnumeratedColumnProgramTableModel<C, R> : DefaultEnumeratedColumnTableModel<C, R>, EnumeratedColumnProgramTableModel<R> where C : Enum<C> , EnumeratedTableColumn<C, R> {
	protected C selColumn;

	private Program program;

	public DefaultEnumeratedColumnProgramTableModel(PluginTool tool, string name, Class<C> colType,
			C selColumn) : base(tool, name, colType)
    {
		if (selColumn != null) {
			Class<object> valueClass = selColumn.getValueClass();
			if (!typeof(Address).isAssignableFrom(valueClass) &&
				!typeof(AddressRange).isAssignableFrom(valueClass) &&
				!typeof(AddressSetView).isAssignableFrom(valueClass)) {
				throw new IllegalArgumentException(
					"Address-selection column must have Address, AddressRange, " +
						"or AddressSetView type");
			}
		}
		this.selColumn = selColumn;
	}

	/* @Override */
	public ProgramLocation getProgramLocation(int row, int column) {
		Class<object> columnClass = getColumnClass(column);
		if (!typeof(Address).isAssignableFrom(columnClass) &&
			!typeof(ProgramLocation).isAssignableFrom(columnClass)) {
			return null;
		}
		object value = getValueAt(row, column);
		if (value is Address) {
			return new ProgramLocation(program, (Address) value);
		}
		if (value is ProgramLocation) {
			return (ProgramLocation) value;
		}
		throw new AssertionError();
	}

	/* @Override */
	public ProgramSelection getProgramSelection(int[] rows) {
